Translate the following GNU C++ code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
﻿#include <bits/stdc++.h>
using namespace std;

#define pb push_back
#define mp make_pair
#define fs first
#define sc second
#define sz(a) ((int) (a).size())
#define int64 long long
#define ldb long double
const ldb pi = acos(-1.0);

const int N = 20;
const double eps = 1e-10;
int n, k;
double a[N], p[1 << N], res[N];

int main() {
	// assert(freopen("input.txt", "r", stdin));
	// assert(freopen("output.txt", "w", stdout));
	scanf("%d%d", &n, &k);
	int cnt = 0;
	for (int i = 0; i < n; ++i) {
		scanf("%lf", &a[i]);
		if (a[i] < eps) ++cnt;
	}
	k = min(n - cnt, k);
	p[0] = 1;
	for (int mask = 1; mask < (1 << n); ++mask) {
		double suma = 0;
		bool ok = true;
		int cnt = 0;
		for (int i = 0; i < n; ++i)
			if (mask & (1 << i)) {
				suma += a[i];
				if (a[i] < eps) ok = false;
				++cnt;
			}
		if (!ok) {
			p[mask] = 0;
			continue;
		} else {
			double sump = 0;
			for (int i = 0; i < n; ++i)
				if (mask & (1 << i))
					sump += a[i] / (1 - suma + a[i]) * p[mask ^ (1 << i)];
			p[mask] = sump;
		}
		if (cnt == k)
			for (int i = 0; i < n; ++i)
				if (mask & (1 << i))
					res[i] += p[mask];
	}
	for (int i = 0; i < n; ++i)
		printf("%.10f%c", res[i], " \n"[i == n - 1]);
	return 0;
}
